from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    row_lines = [
        r for r in range(h)
        if sum(grid[r][c] == background for c in range(w)) < w / 2
    ]
    col_lines = [
        c for c in range(w)
        if sum(grid[r][c] == background for r in range(h)) < h / 2
    ]

    if len(row_lines) < 2 or len(col_lines) < 2:
        return [row[:] for row in grid]

    row_set, col_set = set(row_lines), set(col_lines)
    line_cells = []
    for r in row_lines:
        for c in range(w):
            if c not in col_set:
                line_cells.append(grid[r][c])
    for c in col_lines:
        for r in range(h):
            if r not in row_set:
                line_cells.append(grid[r][c])

    non_background = [v for v in line_cells if v != background]
    separator = Counter(non_background).most_common(1)[0][0] if non_background else background

    out = [[background for _ in range(len(col_lines) - 1)]
           for _ in range(len(row_lines) - 1)]

    for i in range(len(row_lines) - 1):
        for j in range(len(col_lines) - 1):
            corners = [
                grid[row_lines[i]][col_lines[j]],
                grid[row_lines[i]][col_lines[j + 1]],
                grid[row_lines[i + 1]][col_lines[j]],
                grid[row_lines[i + 1]][col_lines[j + 1]],
            ]
            if corners[0] != background and corners[0] != separator and all(
                v == corners[0] for v in corners
            ):
                out[i][j] = corners[0]

    active = [
        (r, c) for r in range(len(out)) for c in range(len(out[0]))
        if out[r][c] != background
    ]
    if not active:
        return out

    r0 = min(r for r, _ in active)
    r1 = max(r for r, _ in active)
    c0 = min(c for _, c in active)
    c1 = max(c for _, c in active)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
